def load_genre_playbooks() -> dict:
    """Load data/genre_playbooks.json once. Missing/invalid file → empty dict."""
    global _GENRE_PLAYBOOKS_CACHE
    if _GENRE_PLAYBOOKS_CACHE is not None:
        return _GENRE_PLAYBOOKS_CACHE
    path = GENRE_PLAYBOOKS_PATH
    if not path.is_file():
        _GENRE_PLAYBOOKS_CACHE = {}
        return _GENRE_PLAYBOOKS_CACHE
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        payload = {}
    _GENRE_PLAYBOOKS_CACHE = payload if isinstance(payload, dict) else {}
    return _GENRE_PLAYBOOKS_CACHE


def _romance_character_archetypes() -> dict | None:
    tags = load_genre_playbooks().get("reference_tags")
    if not isinstance(tags, dict):
        return None
    archetypes = tags.get("romance_character_archetypes")
    return archetypes if isinstance(archetypes, dict) else None


def load_genre_playbook(main_genre, sub_genre) -> dict | None:
    """Return the playbook for `{main}_{sub}`, or None if that pair is not defined.

    Romance books also carry `reference_tags` from the shared romance archetype dictionary.
    """
    main = str(main_genre or "").strip().lower()
    sub = str(sub_genre or "").strip().lower()
    if not main or not sub:
        return None
    item = load_genre_playbooks().get(f"{main}_{sub}")
    if not isinstance(item, dict):
        return None
    if main != "romance":
        return item
    archetypes = _romance_character_archetypes()
    if not archetypes:
        return item
    book = dict(item)
    book["reference_tags"] = archetypes
    return book


def load_genre_playbook_delta(main_genre, sub_genre, genre_detail) -> dict | None:
    """Return `deltas[{main}_{sub}__{detail}]`, or nested `_delta[detail]`. Missing → None."""
    detail = str(genre_detail or "").strip().lower()
    main = str(main_genre or "").strip().lower()
    sub = str(sub_genre or "").strip().lower()
    if not detail or not main or not sub:
        return None
    books = load_genre_playbooks()
    raw_deltas = books.get("deltas")
    if isinstance(raw_deltas, dict):
        item = raw_deltas.get(f"{main}_{sub}__{detail}")
        if isinstance(item, dict):
            return item
    book = books.get(f"{main}_{sub}")
    if not isinstance(book, dict):
        return None
    nested = book.get("_delta")
    if not isinstance(nested, dict):
        return None
    item = nested.get(detail)
    return item if isinstance(item, dict) else None


def _playbook_delta_rules(delta: dict) -> dict:
    rules = delta.get("group_rules_addition")
    if isinstance(rules, dict):
        return rules
    rules = delta.get("group_rules")
    return rules if isinstance(rules, dict) else {}


def _format_playbook_block(heading: str, primary, secondary) -> str:
    primary_text = str(primary or "").strip()
    secondary_text = str(secondary or "").strip()
    if not primary_text and not secondary_text:
        return ""
    parts = [heading]
    if primary_text:
        parts.append(primary_text)
    if secondary_text:
        parts.append(secondary_text)
    return "\n".join(parts)


def _append_playbook_delta_block(base: str, extra: str) -> str:
    if not extra:
        return base
    if not base:
        return extra
    return base + "\n\n" + extra


def _join_playbook_tag_list(value) -> str:
    if not isinstance(value, list):
        return ""
    parts = [str(item).strip() for item in value if str(item).strip()]
    return ", ".join(parts)


def format_genre_playbook_reference_tags_section(main_genre, book=None) -> str:
    """Shared romance archetype vocabulary. Fantasy and missing tags → empty."""
    if str(main_genre or "").strip().lower() != "romance":
        return ""
    tags = book.get("reference_tags") if isinstance(book, dict) else None
    if not isinstance(tags, dict):
        tags = _romance_character_archetypes()
    if not isinstance(tags, dict):
        return ""
    male = _join_playbook_tag_list(tags.get("male"))
    female = _join_playbook_tag_list(tags.get("female"))
    relationships = _join_playbook_tag_list(tags.get("relationship_structures"))
    devices = _join_playbook_tag_list(tags.get("narrative_devices"))
    moods = _join_playbook_tag_list(tags.get("mood_tags"))
    if not any((male, female, relationships, devices, moods)):
        return ""
    return "\n".join(
        [
            GENRE_PLAYBOOK_REFERENCE_TAGS_HEADING,
            "이 장르에서 흔히 쓰이는 캐릭터 유형·관계구도·서사장치 키워드입니다. "
            "아래 나열된 유형(예: 집착남, 걸크러시, 회귀/타임슬립 등)이 등장하면 이는 장르 클리셰이므로 "
            "존재 자체를 지적하지 말고, 그 유형의 특성이 캐릭터 안에서 일관되게 유지되는지만 판단하세요.",
            f"남주 유형: {male}",
            f"여주 유형: {female}",
            f"관계구도: {relationships}",
            f"서사장치: {devices}",
            f"분위기: {moods}",
        ]
    )


def _with_playbook_reference_tags(section: str, main_genre, book=None) -> str:
    if not section:
        return ""
    return _append_playbook_delta_block(
        section, format_genre_playbook_reference_tags_section(main_genre, book)
    )


def _drop_reference_tags_if_present(section: str, text: str) -> str:
    if GENRE_PLAYBOOK_REFERENCE_TAGS_HEADING not in text:
        return section
    idx = section.find(GENRE_PLAYBOOK_REFERENCE_TAGS_HEADING)
    if idx < 0:
        return section
    return section[:idx].rstrip()


def format_genre_playbook_judge_section(main_genre, sub_genre, genre_detail="") -> str:
    """A-group judge block, plus optional `[세부장르 추가 기준]` when `_delta` exists."""
    book = load_genre_playbook(main_genre, sub_genre)
    if not book:
        return ""
    rules = book.get("group_rules") if isinstance(book.get("group_rules"), dict) else {}
    base = _format_playbook_block(
        GENRE_PLAYBOOK_JUDGE_HEADING,
        book.get("checklist"),
        rules.get("A_judge"),
    )
    if not base:
        return ""
    result = base
    delta = load_genre_playbook_delta(main_genre, sub_genre, genre_detail)
    if delta:
        d_rules = _playbook_delta_rules(delta)
        extra = _format_playbook_block(
            GENRE_PLAYBOOK_DETAIL_JUDGE_HEADING,
            delta.get("checklist_addition") or delta.get("checklist"),
            d_rules.get("A_judge"),
        )
        result = _append_playbook_delta_block(base, extra)
    return _with_playbook_reference_tags(result, main_genre, book)


def inject_genre_playbook_judge_section(
    prompt: str, main_genre, sub_genre, genre_detail="", content_rating=""
) -> str:
    """Insert the A-group playbook section before [본문]. Idempotent; no-op if missing."""
    section = format_genre_playbook_judge_section(main_genre, sub_genre, genre_detail)
    text = str(prompt or "")
    needles = ("[본문]", "[원본 마지막 3문단]")
    if not section or GENRE_PLAYBOOK_JUDGE_HEADING in text:
        return inject_content_rating_section(text, main_genre, content_rating, "judge", needles)
    section = _drop_reference_tags_if_present(section, text)
    if not section:
        return inject_content_rating_section(text, main_genre, content_rating, "judge", needles)
    for needle in needles:
        idx = text.find(needle)
        if idx >= 0:
            text = text[:idx] + section + "\n\n" + text[idx:]
            break
    else:
        text = text + "\n\n" + section
    return inject_content_rating_section(text, main_genre, content_rating, "judge", needles)


def format_genre_playbook_suggest_section(main_genre, sub_genre, genre_detail="") -> str:
    """B-group suggest block, plus optional `[세부장르 추가 기준]` when `_delta` exists."""
    book = load_genre_playbook(main_genre, sub_genre)
    if not book:
        return ""
    rules = book.get("group_rules") if isinstance(book.get("group_rules"), dict) else {}
    base = _format_playbook_block(
        GENRE_PLAYBOOK_JUDGE_HEADING,
        book.get("reader_expectations"),
        rules.get("B_suggest"),
    )
    if not base:
        return ""
    result = base
    delta = load_genre_playbook_delta(main_genre, sub_genre, genre_detail)
    if delta:
        d_rules = _playbook_delta_rules(delta)
        extra = _format_playbook_block(
            GENRE_PLAYBOOK_DETAIL_JUDGE_HEADING,
            delta.get("reader_expectations_addition") or delta.get("reader_expectations"),
            d_rules.get("B_suggest"),
        )
        result = _append_playbook_delta_block(base, extra)
    return _with_playbook_reference_tags(result, main_genre, book)


def inject_genre_playbook_suggest_section(
    prompt: str, main_genre, sub_genre, genre_detail="", content_rating=""
) -> str:
    """Insert the B-group playbook section before the manuscript block. Idempotent.

    content_rating is accepted for call-site symmetry and is never injected (B-group).
    """
    del content_rating
    section = format_genre_playbook_suggest_section(main_genre, sub_genre, genre_detail)
    text = str(prompt or "")
    if not section or GENRE_PLAYBOOK_JUDGE_HEADING in text:
        return text
    section = _drop_reference_tags_if_present(section, text)
    if not section:
        return text
    for needle in (
        "[현재 회차 본문]",
        "[현재 회차 또는 최근 원고]",
        "[직전 회차 마지막 부분]",
        "[작가가 제공한 줄거리 개요 - 시작부터 결말까지]",
        "[작가가 제공한 줄거리 개요]\n(제공되지 않음",
        "[본문]",
        "[원본 마지막 3문단]",
        "[현재 회차]",
        "[제출용 자료]",
    ):
        idx = text.find(needle)
        if idx >= 0:
            return text[:idx] + section + "\n\n" + text[idx:]
    return text + "\n\n" + section


def format_genre_playbook_style_section(main_genre, sub_genre, genre_detail="") -> str:
    """C-group style block, plus optional `[세부장르 추가 문체 기준]` when `_delta` exists."""
    book = load_genre_playbook(main_genre, sub_genre)
    if not book:
        return ""
    rules = book.get("group_rules") if isinstance(book.get("group_rules"), dict) else {}
    base = _format_playbook_block(
        GENRE_PLAYBOOK_STYLE_HEADING,
        book.get("tone"),
        rules.get("C_style"),
    )
    if not base:
        return ""
    result = base
    delta = load_genre_playbook_delta(main_genre, sub_genre, genre_detail)
    if delta:
        d_rules = _playbook_delta_rules(delta)
        extra = _format_playbook_block(
            GENRE_PLAYBOOK_DETAIL_STYLE_HEADING,
            delta.get("tone_addition") or delta.get("tone"),
            d_rules.get("C_style"),
        )
        result = _append_playbook_delta_block(base, extra)
    return _with_playbook_reference_tags(result, main_genre, book)


def inject_genre_playbook_style_section(
    prompt: str, main_genre, sub_genre, genre_detail="", content_rating=""
) -> str:
    """Insert the C-group style section before the manuscript block. Idempotent."""
    section = format_genre_playbook_style_section(main_genre, sub_genre, genre_detail)
    text = str(prompt or "")
    needles = (
        "[원고]",
        "[앞뒤 맥락 - 참고용, 다듬지 않음]",
        "[다듬을 문장]",
        "[선택 원문]",
        "[현재 회차 - 문체 참고용]",
        "[본문]",
    )
    if not section or GENRE_PLAYBOOK_STYLE_HEADING in text:
        return inject_content_rating_section(text, main_genre, content_rating, "style", needles)
    section = _drop_reference_tags_if_present(section, text)
    if not section:
        return inject_content_rating_section(text, main_genre, content_rating, "style", needles)
    for needle in needles:
        idx = text.find(needle)
        if idx >= 0:
            text = text[:idx] + section + "\n\n" + text[idx:]
            break
    else:
        text = text + "\n\n" + section
    return inject_content_rating_section(text, main_genre, content_rating, "style", needles)


def parse_content_rating(value) -> str:
    """Empty/missing → ''. Allowed keys pass through. Anything else raises."""
    if value is None:
        return ""
    key = str(value).strip().lower()
    if not key:
        return ""
    if key not in CONTENT_RATING_ALLOWED:
        raise ValueError("표현 수위 값이 올바르지 않습니다.")
    return key


def content_rating_heading(key: str) -> str:
    label = CONTENT_RATING_LABELS.get(key, "")
    if not label:
        return ""
    return f"{CONTENT_RATING_HEADING_PREFIX} - {label}]"


def format_content_rating_section(main_genre, content_rating, kind: str) -> str:
    """Romance-only overlay. Empty/unknown rating or non-romance → no section."""
    if str(main_genre or "").strip().lower() != "romance":
        return ""
    key = str(content_rating or "").strip().lower()
    if key not in CONTENT_RATING_ALLOWED:
        return ""
    heading = content_rating_heading(key)
    if not heading:
        return ""
    blob = load_genre_playbooks().get("content_ratings")
    if not isinstance(blob, dict):
        return ""
    if kind == "style":
        principles = blob.get("style_principles")
        body = principles.get(key) if isinstance(principles, dict) else ""
        body = str(body or "").strip()
        if not body:
            return ""
        return heading + "\n" + body
    principles = blob.get("judge_principles")
    principle = principles.get(key) if isinstance(principles, dict) else ""
    principle = str(principle or "").strip()
    common = str(blob.get("judge_common") or "").strip()
    if not principle and not common:
        return ""
    parts = [heading]
    if principle:
        parts.append(principle)
    if common:
        parts.append(common)
    return "\n".join(parts)


def inject_content_rating_section(
    prompt: str,
    main_genre,
    content_rating,
    kind: str,
    needles: tuple[str, ...] = ("[본문]",),
) -> str:
    """Insert `[표현 수위 기준 - …]` before the manuscript marker. Idempotent."""
    text = str(prompt or "")
    section = format_content_rating_section(main_genre, content_rating, kind)
    if not section:
        return text
    heading = section.split("\n", 1)[0]
    if heading in text or CONTENT_RATING_HEADING_PREFIX in text:
        return text
    for needle in needles:
        idx = text.find(needle)
        if idx >= 0:
            return text[:idx] + section + "\n\n" + text[idx:]
    return text + "\n\n" + section


def connect() -> sqlite3.Connection:
    connection = sqlite3.connect(DATABASE_PATH)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys = ON")
    connection.execute("PRAGMA journal_mode = WAL")
    return connection


@contextmanager
def database() -> sqlite3.Connection:
    """Commit successful requests and always close the Windows file handle."""
    connection = connect()
    try:
        yield connection
        connection.commit()
    except Exception:
        connection.rollback()
        raise
    finally:
        connection.close()


def projects_root() -> Path:
    """External .stg files live next to the data folder (or under the app root)."""
    if _PROJECTS_DIR_ENV:
        return Path(_PROJECTS_DIR_ENV).expanduser()
    # Prefer a sibling of data/ so tests that swap DATA_DIR stay isolated.
    return project_package.projects_dir(DATA_DIR.parent if DATA_DIR.name == "data" else ROOT)


def default_export_dir() -> Path:
    """Default folder for manuscript exports: Downloads (다운로드)."""
    home = Path.home()
    for name in ("Downloads", "다운로드"):
        candidate = home / name
        if candidate.is_dir():
            return candidate
    # Prefer creating the common English name if neither exists yet.
    return home / "Downloads"


def export_prefs_path() -> Path:
    return DATA_DIR / "export_prefs.json"


def load_export_prefs() -> dict:
    path = export_prefs_path()
    prefs: dict = {
        "export_dir": str(default_export_dir()),
        "save_to_folder": True,
        "reveal_after_save": True,
    }
    if path.is_file():
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(raw, dict):
                if raw.get("export_dir"):
                    prefs["export_dir"] = str(raw["export_dir"])
                if "save_to_folder" in raw:
                    prefs["save_to_folder"] = bool(raw["save_to_folder"])
                if "reveal_after_save" in raw:
                    prefs["reveal_after_save"] = bool(raw["reveal_after_save"])
        except (OSError, json.JSONDecodeError, TypeError, ValueError):
            pass
    return prefs


def save_export_prefs(prefs: dict) -> dict:
    DATA_DIR.mkdir(exist_ok=True)
    cleaned = {
        "export_dir": str(prefs.get("export_dir") or default_export_dir()),
        "save_to_folder": bool(prefs.get("save_to_folder", True)),
        "reveal_after_save": bool(prefs.get("reveal_after_save", True)),
    }
    export_prefs_path().write_text(
        json.dumps(cleaned, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    return cleaned


def resolve_export_dir(raw: str | None = None, *, create: bool = True) -> Path:
    """
    Resolve and validate an export directory on this machine.
    Allowed roots: user home, Documents, Desktop, Downloads, app data/projects.
    """
    prefs = load_export_prefs()
    text = str(raw if raw is not None else prefs.get("export_dir") or "").strip()
    if not text:
        path = default_export_dir()
    else:
        path = Path(text).expanduser()
    try:
        path = path.resolve()
    except OSError as error:
        raise ValueError(f"폴더 경로를 해석할 수 없습니다: {error}") from error

    home = Path.home().resolve()
    allowed_roots = [
        home,
        home / "Documents",
        home / "Desktop",
        home / "Downloads",
        home / "OneDrive",
        home / "OneDrive" / "Documents",
        DATA_DIR.resolve(),
        projects_root().resolve(),
        ROOT.resolve(),
    ]
    # Also allow any existing path under home
    under_home = False
    try:
        path.relative_to(home)
        under_home = True
    except ValueError:
        under_home = False
    if not under_home:
        ok = False
        for root in allowed_roots:
            try:
                if root.exists():
                    path.relative_to(root)
                    ok = True
                    break
            except ValueError:
                continue
        if not ok:
            raise ValueError(
                "저장 폴더는 사용자 폴더(내 문서·바탕화면 등) 아래로만 지정할 수 있어요."
            )

    if create:
        try:
            path.mkdir(parents=True, exist_ok=True)
        except OSError as error:
            raise ValueError(f"폴더를 만들 수 없습니다: {error}") from error
    if path.exists() and not path.is_dir():
        raise ValueError("지정한 경로는 폴더가 아닙니다.")
    return path


def safe_export_filename(name: str) -> str:
    base = str(name or "export").strip() or "export"
    base = re.sub(r'[<>:"/\\|?*\x00-\x1f]', "_", base)
    base = base.strip(" .") or "export"
    return base[:180]


def write_export_file(
    data: bytes,
    filename: str,
    *,
    directory: str | None = None,
    reveal: bool | None = None,
) -> dict:
    """Write export bytes to the configured (or given) folder on this PC."""
    prefs = load_export_prefs()
    folder = resolve_export_dir(directory, create=True)
    name = safe_export_filename(filename)
    target = folder / name
    # Avoid overwrite: add (2), (3)...
    if target.exists():
        stem = target.stem
        suffix = target.suffix
        n = 2
        while True:
            candidate = folder / f"{stem} ({n}){suffix}"
            if not candidate.exists():
                target = candidate
                break
            n += 1
            if n > 999:
                raise ValueError("같은 이름 파일이 너무 많아 저장하지 못했어요.")
    try:
        target.write_bytes(data)
    except OSError as error:
        raise ValueError(f"파일 저장에 실패했습니다: {error}") from error
    do_reveal = prefs.get("reveal_after_save", True) if reveal is None else bool(reveal)
    if do_reveal:
        try:
            reveal_in_explorer(target)
        except Exception:
            pass
    return {
        "path": str(target),
        "folder": str(folder),
        "filename": target.name,
        "bytes": len(data),
        "revealed": bool(do_reveal),
    }


def _migrate_legacy_database_file() -> None:
    """Rename storyguide.sqlite3 → supertory.sqlite3 when only the old name exists."""
    new_path = Path(DATABASE_PATH)
    if new_path.is_file():
        return
    legacy = new_path.with_name("storyguide.sqlite3")
    if not legacy.is_file():
        return
    try:
        legacy.rename(new_path)
        for suffix in ("-wal", "-shm"):
            old_side = Path(str(legacy) + suffix)
            new_side = Path(str(new_path) + suffix)
            if old_side.is_file() and not new_side.exists():
                old_side.rename(new_side)
        print(f"데이터베이스 파일 이름 변경: {legacy.name} → {new_path.name}")
    except OSError as error:
        print(f"레거시 DB 이름 변경 실패 ({legacy} → {new_path}): {error}")


