def _scene_id_is_notnull(connection: sqlite3.Connection, table: str) -> bool:
    try:
        for row in connection.execute(f"PRAGMA table_info({table})").fetchall():
            if str(row[1]) == "scene_id":
                return int(row[3] or 0) == 1
    except sqlite3.Error:
        return False
    return False


