def _parse_fill_blank_skeleton(raw: object) -> list[dict]:
    cleaned = SuperToryHandler._strip_json_fence(str(raw or "")).strip()
    data: object
    try:
        data = json.loads(cleaned)
    except json.JSONDecodeError:
        match = re.search(r"\{.*\}", cleaned, re.S)
        if not match:
            raise ValueError("json")
        data = json.loads(match.group(0))
    if isinstance(data, dict):
        segments_raw = data.get("segments")
        if segments_raw is None:
            segments_raw = data.get("items") or data.get("skeleton")
    else:
        segments_raw = data
    if not isinstance(segments_raw, list) or not segments_raw:
        raise ValueError("json")
    segments: list[dict] = []
    used_ids: set[str] = set()
    blank_n = 0
    for item in segments_raw:
        if not isinstance(item, dict):
            continue
        kind = str(item.get("type") or "").strip().lower()
        if kind in {"text", "given", "fixed_text"}:
            kind = "fixed"
        if kind == "fixed":
            text = str(item.get("text") or item.get("content") or "")
            segments.append({"type": "fixed", "text": text})
            continue
        if kind not in {"blank", "fill", "slot"}:
            continue
        blank_n += 1
        blank_id = str(item.get("id") or "").strip() or f"b{blank_n}"
        if blank_id in used_ids:
            suffix = 2
            while f"{blank_id}_{suffix}" in used_ids:
                suffix += 1
            blank_id = f"{blank_id}_{suffix}"
        used_ids.add(blank_id)
        hint = str(item.get("hint") or item.get("prompt") or item.get("label") or "").strip()
        if not hint:
            hint = "이 칸을 채워 주세요"
        segments.append({"type": "blank", "id": blank_id, "hint": hint})
    blank_count = sum(1 for item in segments if item["type"] == "blank")
    if blank_count < FILL_BLANK_MIN_BLANKS or blank_count > FILL_BLANK_MAX_BLANKS:
        raise ValueError("json")
    if not any(item["type"] == "fixed" for item in segments):
        raise ValueError("json")
    return segments


def _assemble_fill_blank_text(segments: list[dict], answers: object) -> str:
    mapping: dict[str, str] = {}
    if isinstance(answers, dict):
        mapping = {str(key): str(value or "") for key, value in answers.items()}
    blank_ids = [item["id"] for item in segments if item.get("type") == "blank"]
    if not blank_ids:
        raise ValueError("빈칸 뼈대가 손상되었습니다.")
    for blank_id in blank_ids:
        if not str(mapping.get(blank_id) or "").strip():
            raise ValueError("모든 빈칸을 채워주세요")
    parts: list[str] = []
    for item in segments:
        if item.get("type") == "fixed":
            parts.append(str(item.get("text") or ""))
            continue
        parts.append(str(mapping.get(item.get("id")) or ""))
    return "".join(parts)


def _parse_pingpong_turns(raw: object) -> list[dict]:
    if isinstance(raw, list):
        data = raw
    else:
        text = str(raw or "").strip() or "[]"
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            return []
    if not isinstance(data, list):
        return []
    turns: list[dict] = []
    for item in data:
        if not isinstance(item, dict):
            continue
        speaker = str(item.get("speaker") or "").strip().lower()
        if speaker in {"author", "writer", "human"}:
            speaker = "user"
        if speaker in {"tory", "ai", "assistant"}:
            speaker = "tori"
        if speaker not in {"user", "tori"}:
            continue
        text = str(item.get("text") or "").strip()
        if not text:
            continue
        turns.append({"speaker": speaker, "text": text})
    return turns


def _format_pingpong_turns(turns: list[dict]) -> str:
    if not turns:
        return "(아직 주고받은 문장이 없습니다. 작가가 첫 문장을 건넵니다.)"
    lines: list[str] = []
    for item in turns:
        who = "작가" if item.get("speaker") == "user" else "토리"
        lines.append(f"{who}: {item.get('text') or ''}")
    text = "\n".join(lines)
    if len(text) > 4000:
        return "…\n" + text[-4000:]
    return text


def _clip_pingpong_reply(raw: object, limit: int = PINGPONG_REPLY_MAX) -> str:
    text = SuperToryHandler._strip_json_fence(str(raw or "")).strip()
    text = re.sub(r"^(토리|Tory)\s*[:：]\s*", "", text).strip()
    if not text:
        return ""
    if len(text) <= limit:
        return text
    truncated = text[:limit]
    for sep in ("다. ", "요. ", "죠. ", "다.", "요.", "죠.", ". ", ".\n"):
        pos = truncated.rfind(sep)
        if pos >= 24:
            end = pos + len(sep.rstrip())
            clipped = truncated[:end].strip()
            if clipped:
                return clipped
    return truncated.rstrip()


def _assemble_pingpong_text(turns: list[dict]) -> str:
    parts = [
        str(item.get("text") or "").strip()
        for item in turns
        if str(item.get("text") or "").strip()
    ]
    return " ".join(parts)


def _pingpong_turn_prompt(
    genre: object,
    episode_content: object,
    character_settings: object,
    turns: object,
) -> tuple[str, str]:
    """Assemble ping-pong relay prompts. Reuses Tory Core Identity as-is."""
    excerpt = _clip_recent_episode(episode_content, PINGPONG_EPISODE_CAP)
    genre_label = str(genre or "").strip() or "미정"
    settings = str(character_settings or "").strip() or "(설정집 인물 없음)"
    parsed = _parse_pingpong_turns(turns)
    core = SuperToryHandler._tory_core_identity_system_prompt()
    dynamic = (
        "[Dynamic Context]\n"
        f"작품 장르: {genre_label}\n\n"
        "[설정집 · 등장인물 이름/말투]\n"
        f"{settings}\n\n"
        "아래는 작가가 막힌 지점의 최근 원고입니다.\n"
        f"{excerpt}\n\n"
        "[이 릴레이에서 지금까지 주고받은 문장]\n"
        f"{_format_pingpong_turns(parsed)}"
    )
    user_prompt = (
        "[Task Instruction]\n"
        "지금 작가와 번갈아가며 소설을 이어 쓰고 있습니다. 작가가 방금 쓴 부분 "
        "다음에 이어질 한두 문장만 쓰세요. 절대 장면을 혼자 마무리 짓거나 여러 문단을 쓰지 마세요 "
        "— 짧게 쓰고 다시 작가에게 넘겨야 합니다. 이야기에 자연스럽게 다음 전개의 여지를 남기되, "
        "지나치게 사건을 크게 벌이지는 마세요. 설정집의 인물 말투와 세계관을 정확히 따르세요.\n\n"
        "출력은 순수 텍스트 한두 문장만 반환하세요. JSON, 제목, 화자 이름, 따옴표 설명은 넣지 마세요."
    )
    return core + "\n" + dynamic, user_prompt


def _lucky_sentence_prompt(genre: object, episode_content: object) -> tuple[str, str]:
    """Assemble Lucky Sentence prompts. Reuses Tory Core Identity as-is."""
    excerpt = _clip_recent_episode(episode_content, LUCKY_SENTENCE_EPISODE_CAP)
    genre_label = str(genre or "").strip() or "미정"
    core = SuperToryHandler._tory_core_identity_system_prompt()
    dynamic = (
        "[Dynamic Context]\n"
        f"작품 장르: {genre_label}\n\n"
        "아래는 작가가 막힌 지점의 최근 원고입니다.\n"
        f"{excerpt}"
    )
    user_prompt = (
        "[Task Instruction]\n"
        "지금 원고 맥락과 어울리면서도, 다음 문단에 자연스럽게 녹여 쓸 수 있는 "
        "인상적인 문장 하나를 만드세요. 이 문장 자체가 다음 내용을 미리 정해버리면 안 되고, "
        "다양한 방향으로 이어질 수 있도록 열려있어야 합니다. 한 문장으로, 20~40자 사이로 "
        "짧고 강렬하게 쓰세요.\n\n"
        "출력은 순수 텍스트 한 문장만 반환하세요. JSON, 따옴표, 설명 문장은 넣지 마세요."
    )
    return core + "\n" + dynamic, user_prompt


def _clip_lucky_sentence(raw: object) -> str:
    text = SuperToryHandler._strip_json_fence(str(raw or "")).strip()
    text = text.strip("「」\"'`").strip()
    text = re.sub(r"\s+", " ", text)
    if not text:
        return ""
    match = re.search(r".+?[.!?。]|[^.!?。]+", text)
    sentence = (match.group(0) if match else text).strip()
    if len(sentence) <= 60:
        return sentence
    return sentence[:40].rstrip()


def _highlight_extraction_prompt(episode_content: object) -> tuple[str, str]:
    """Assemble Mental Vitamin highlight prompts. Reuses Tory Core Identity as-is."""
    excerpt = str(episode_content or "").strip()
    core = SuperToryHandler._tory_core_identity_system_prompt()
    user_prompt = (
        "[Task Instruction]\n"
        "다음 원고에서 아래 3가지를 찾을 수 있는 만큼 뽑으세요 (없으면 생략 가능):\n"
        "1. 대사: 캐릭터의 개성이나 감정이 가장 잘 드러난 대사 한 줄\n"
        "2. 묘사: 문장 리듬이나 표현이 인상적인 묘사 한 부분\n"
        "3. 장면: 감정선이나 전개가 특히 잘 짜인 장면 한 부분\n"
        "각각 원문 그대로 발췌하고, 왜 뽑았는지 한 줄 이유를 덧붙이세요. "
        "특별히 눈에 띄는 게 없으면 억지로 뽑지 말고 빈 배열을 반환하세요.\n\n"
        "출력은 JSON 배열만 반환하세요. 설명 문장이나 마크다운 코드펜스를 넣지 마세요.\n"
        '형식: [{"type": "dialogue", "excerpt": "...", "reason": "..."}, ...]\n'
        "type은 dialogue / description / scene 중 하나입니다. 항목은 0~3개입니다.\n\n"
        "[원고]\n"
        f"{excerpt}"
    )
    return core, user_prompt


def _parse_highlight_moments(raw: object) -> list[dict]:
    cleaned = SuperToryHandler._strip_json_fence(str(raw or "")).strip()
    if not cleaned or cleaned in {"[]", "null", "None"}:
        return []
    data: object
    try:
        data = json.loads(cleaned)
    except json.JSONDecodeError:
        match = re.search(r"\[.*\]", cleaned, re.S)
        if not match:
            raise ValueError("json")
        data = json.loads(match.group(0))
    if isinstance(data, dict):
        data = data.get("moments") or data.get("items") or data.get("highlights") or []
    if not isinstance(data, list):
        raise ValueError("json")
    seen_types: set[str] = set()
    moments: list[dict] = []
    for item in data:
        if not isinstance(item, dict):
            continue
        kind = str(item.get("type") or item.get("moment_type") or "").strip().lower()
        excerpt = str(item.get("excerpt") or item.get("text") or "").strip()
        reason = str(item.get("reason") or item.get("why") or "").strip()
        if kind not in GLUMP_HIGHLIGHT_TYPES:
            continue
        if kind in seen_types:
            continue
        if not excerpt or not reason:
            continue
        seen_types.add(kind)
        moments.append({"type": kind, "excerpt": excerpt, "reason": reason})
        if len(moments) == 3:
            break
    return moments


def _highlight_char_count(content: object) -> tuple[str, int]:
    plain = plain_text_from_content(str(content or ""))
    return plain, len(plain)


def list_scenes_in_binder_order(
    connection: sqlite3.Connection, project_id: int
) -> list[dict]:
    """Active scenes in binder folder DFS order (same walk as getEpisodeSequence)."""
    handler = object.__new__(SuperToryHandler)
    return handler._list_scenes_in_binder_order(connection, int(project_id))


def _scene_episode_order(connection: sqlite3.Connection, project_id: int, scene_id: int) -> int:
    for index, scene in enumerate(
        list_scenes_in_binder_order(connection, project_id), start=1
    ):
        if int(scene["id"]) == int(scene_id):
            return index
    return 0


def _upsert_highlight_progress(
    connection: sqlite3.Connection, episode_id: str, length: int
) -> None:
    stamp = utc_timestamp_now()
    connection.execute(
        """
        INSERT INTO glump_highlight_progress (episode_id, last_analyzed_length, updated_at)
        VALUES (?, ?, ?)
        ON CONFLICT(episode_id) DO UPDATE SET
            last_analyzed_length = excluded.last_analyzed_length,
            updated_at = excluded.updated_at
        """,
        (episode_id, int(length), stamp),
    )


def schedule_scenes_snapshot_sync(project_id: int) -> None:
    """Fire-and-forget manuscript snapshot to Supabase. Must not block checkout."""
    try:
        worker = Thread(
            target=_scenes_snapshot_worker,
            args=(int(project_id),),
            daemon=True,
            name=f"scenes-snapshot-{project_id}",
        )
        worker.start()
    except Exception:
        pass


def _scenes_snapshot_worker(project_id: int) -> None:
    try:
        sync_scenes_snapshot(int(project_id))
    except Exception:
        pass


def schedule_glump_highlight_analysis(scene_id: int, content: str) -> None:
    """Fire-and-forget highlight scan. Must never block the save path."""
    try:
        worker = Thread(
            target=_glump_highlight_worker,
            args=(int(scene_id), str(content or "")),
            daemon=True,
            name=f"glump-highlight-{scene_id}",
        )
        worker.start()
    except Exception:
        pass


def _glump_highlight_worker(scene_id: int, content: str) -> None:
    try:
        maybe_extract_glump_highlights(scene_id, content)
    except Exception:
        pass


def maybe_extract_glump_highlights(scene_id: int, content: str) -> None:
    """Analyze newly added manuscript text for Mental Vitamin, if +500 chars."""
    episode_key = str(int(scene_id))
    with _glump_highlight_inflight_lock:
        if episode_key in _glump_highlight_inflight:
            return
        _glump_highlight_inflight.add(episode_key)
    try:
        _extract_glump_highlights_unlocked(scene_id, content)
    finally:
        with _glump_highlight_inflight_lock:
            _glump_highlight_inflight.discard(episode_key)


def _extract_glump_highlights_unlocked(scene_id: int, content: str) -> None:
    if not gemini_client.is_configured():
        return
    plain, current_len = _highlight_char_count(content)
    with database() as connection:
        scene = connection.execute(
            "SELECT project_id FROM scene WHERE id = ? AND deleted_at IS NULL",
            (scene_id,),
        ).fetchone()
        if scene is None:
            return
        work_id = str(scene["project_id"])
        progress = connection.execute(
            "SELECT last_analyzed_length FROM glump_highlight_progress "
            "WHERE episode_id = ?",
            (str(scene_id),),
        ).fetchone()
        last_len = int(progress["last_analyzed_length"] or 0) if progress else 0
        if current_len < last_len:
            _upsert_highlight_progress(connection, str(scene_id), current_len)
            return
        if current_len - last_len < GLUMP_HIGHLIGHT_MIN_CHARS:
            return
        episode_order = _scene_episode_order(
            connection, int(scene["project_id"]), int(scene_id)
        )
    chunk = plain[last_len:]
    if len(chunk) > GLUMP_HIGHLIGHT_CHUNK_MAX:
        chunk = chunk[-GLUMP_HIGHLIGHT_CHUNK_MAX:]
    if len(chunk.strip()) < GLUMP_HIGHLIGHT_MIN_CHARS:
        with database() as connection:
            _upsert_highlight_progress(connection, str(scene_id), current_len)
        return
    system, user_prompt = _highlight_extraction_prompt(chunk)
    try:
        raw = gemini_client.generate_text(
            user_prompt, system=system, temperature=0.4
        )
        moments = _parse_highlight_moments(raw)
    except Exception:
        return
    stamp = utc_timestamp_now()
    with database() as connection:
        for item in moments:
            connection.execute(
                """
                INSERT INTO glump_highlight_moments
                    (id, work_id, episode_id, episode_order, moment_type,
                     excerpt, reason, created_at)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    uuid.uuid4().hex,
                    work_id,
                    str(scene_id),
                    int(episode_order or 0),
                    item["type"],
                    item["excerpt"],
                    item["reason"],
                    stamp,
                ),
            )
        live = connection.execute(
            "SELECT content_md FROM scene_revision "
            "WHERE scene_id = ? AND is_current = 1",
            (scene_id,),
        ).fetchone()
        live_len = current_len
        if live is not None:
            live_len = _highlight_char_count(live["content_md"])[1]
        _upsert_highlight_progress(
            connection, str(scene_id), min(current_len, live_len)
        )


def pick_mental_vitamin_moments(rows: list) -> list[dict]:
    """Newest-first: fill dialogue/description/scene, skip same type in the same episode."""
    picked: list[dict] = []
    have_types: set[str] = set()
    seen_episode_type: set[tuple[str, str]] = set()
    for row in rows:
        kind = str(row["moment_type"] or "").strip()
        episode_id = str(row["episode_id"] or "")
        if kind not in GLUMP_HIGHLIGHT_TYPES or kind in have_types:
            continue
        marker = (episode_id, kind)
        if marker in seen_episode_type:
            continue
        seen_episode_type.add(marker)
        have_types.add(kind)
        picked.append(
            {
                "type": kind,
                "excerpt": str(row["excerpt"] or ""),
                "reason": str(row["reason"] or ""),
                "episode_id": episode_id,
                "episode_order": int(row["episode_order"] or 0),
            }
        )
        if len(have_types) == 3:
            break
    return picked


def _glump_work_genre_label(work_id: object) -> str:
    work_key = str(work_id or "").strip()
    if not work_key:
        raise ValueError("작품을 선택해 주세요.")
    with database() as connection:
        row = connection.execute(
            "SELECT main_genre, sub_genre FROM project "
            "WHERE id = ? AND deleted_at IS NULL",
            (work_key,),
        ).fetchone()
    if row is None:
        raise LookupError("작품을 찾을 수 없습니다.")
    main = SuperToryHandler._genre_display_label(None, str(row["main_genre"] or ""))
    sub = SuperToryHandler._genre_display_label(None, str(row["sub_genre"] or ""))
    if sub and sub != "미정":
        return f"{main} / {sub}"
    return main


def _as_string_list(value: object) -> list[str]:
    """Parse a JSON array (or already-decoded list) into non-empty strings."""
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    text = str(value or "").strip()
    if not text:
        return []
    try:
        parsed = json.loads(text)
    except json.JSONDecodeError:
        return [text]
    if isinstance(parsed, list):
        return [str(item).strip() for item in parsed if str(item).strip()]
    return [text]


def serialize_reader_persona(row: sqlite3.Row | dict) -> dict:
    item = dict(row)
    item["criteria"] = _as_string_list(item.get("criteria"))
    item["sample_responses"] = _as_string_list(item.get("sample_responses"))
    item["display_order"] = int(item.get("display_order") or 0)
    return item


def reader_chat_session_key(work_id: object, persona_id: object) -> str:
    return f"reader_chat_{work_id}_{persona_id}"


def parse_reader_debate_persona_ids(raw: object) -> list[str]:
    """Normalize persona id list (array or comma-separated), preserving order."""
    if isinstance(raw, str):
        parts = [part.strip() for part in raw.split(",") if part.strip()]
    elif isinstance(raw, (list, tuple)):
        parts = [str(part).strip() for part in raw if str(part).strip()]
    else:
        parts = []
    return parts


def reader_debate_persona_ids_key(persona_ids: list[str]) -> str:
    """Sorted comma key for session reuse (order-independent lookup)."""
    return ",".join(sorted({str(pid).strip() for pid in persona_ids if str(pid).strip()}))


def _reader_debate_system_prompt(persona: dict, shared_context: str) -> str:
    """Reuse 1:1 persona prompt + debate task line + shared work context."""
    return (
        _reader_persona_system_prompt(persona)
        + "\n"
        + READER_DEBATE_TASK_ADDON
        + "\n\n"
        + shared_context
    )


def _reader_debate_user_prompt(
    reader_name: str, transcript: str, user_message: str
) -> str:
    return (
        f"아래는 작가와 여러 가상 독자의 토론, 그리고 작가의 새 메시지입니다. "
        f"당신은 '{reader_name}'로서 새 메시지와 다른 독자들의 발언에 이어서 답하세요. "
        f"이름 접두어는 붙이지 마세요.\n\n"
        f"[지금까지의 토론]\n{transcript}\n\n"
        f"[작가의 새 메시지]\n{user_message}"
    )


def _reader_debate_transcript_lines(
    rows: list[dict], persona_names: dict[str, str]
) -> list[str]:
    lines: list[str] = []
    for item in rows:
        content = str(item.get("message") or "").strip()
        if not content:
            continue
        if len(content) > 4000:
            content = content[:4000] + "…"
        speaker = str(item.get("speaker_type") or "").strip().lower()
        if speaker == "user":
            who = "작가"
        else:
            pid = str(item.get("persona_id") or "").strip()
            who = persona_names.get(pid) or "가상 독자"
        lines.append(f"{who}: {content}")
    return lines


def _reader_persona_system_prompt(persona_row: dict) -> str:
    """Build a 1:1 virtual-reader system prompt from a single persona row.

    Only this reader's fields are injected. Other personas and Tory's
    Core Identity must never appear here.
    """
    persona = serialize_reader_persona(persona_row)
    name = str(persona.get("name") or "").strip() or "가상 독자"
    identity = str(persona.get("identity") or "").strip() or "(없음)"
    tone = str(persona.get("tone") or "").strip() or "(없음)"
    forbidden = str(persona.get("forbidden") or "").strip() or "(없음)"
    criteria = persona.get("criteria") or []
    if criteria:
        criteria_block = "\n".join(
            f"{index}. {line}" for index, line in enumerate(criteria, start=1)
        )
    else:
        criteria_block = "(없음)"
    samples = (persona.get("sample_responses") or [])[:3]
    if samples:
        sample_block = "\n".join(f"- {line}" for line in samples)
    else:
        sample_block = "(없음)"
    prompt = (
        "[Core Identity]\n"
        f"당신은 '{name}'이라는 이름의 가상 독자입니다.\n\n"
        "[정체성]\n"
        f"{identity}\n\n"
        "[말투]\n"
        f"{tone}\n\n"
        "[평가 우선순위]\n"
        "아래 순서는 이 독자가 작품을 볼 때 더 중요하게 여기는 기준입니다. "
        "앞번호일수록 판단에 더 큰 비중을 두세요.\n"
        f"{criteria_block}\n\n"
        "[금지사항]\n"
        f"{forbidden}\n\n"
        "[말투 예시]\n"
        "아래는 이 독자의 말투·반응 방식을 참고하기 위한 예시입니다. "
        "문장을 그대로 따라 말하지 말고, 톤과 반응의 결만 참고하세요.\n"
        f"{sample_block}\n\n"
        "중요: 당신은 이 독자 한 명뿐입니다. 다른 가상 독자의 취향·말투·평가 기준을 "
        "끌어오거나 언급하지 마세요. 토리(SuperTORY 조력자)가 아니며, "
        "편집자·비평가 페르소나를 섞지 마세요.\n\n"
        "[Task Instruction]\n"
        "당신은 지금 작가와 1:1로 대화 중입니다. 작가가 보여주는 원고나 질문에 대해 "
        "위에서 정의된 당신의 캐릭터를 유지하며 반응하세요.\n"
        "당신은 AI라는 사실을 언급하지 말고, 실제 독자처럼 자연스럽게 반응하세요.\n"
        "평가 우선순위에 따라 반응하되, 항상 그 이유를 함께 설명하세요.\n"
        "제공된 시놉시스·세계관·원고에 명시되지 않은 플롯 장치나 설정(예: 회빙환, 빙의, 환생, "
        "숨겨진 정체 등)을 임의로 가정해서 언급하지 마라. 확인되지 않은 부분에 대해서는 "
        "'본문/설정에 안 나와서 모르겠다' 또는 '~인가요?'처럼 되묻는 방식으로 반응해라."
    )
    persona_id = str(persona.get("id") or "").strip()
    # 개연성·복선 설계 분석가만 누적 인덱스 떡밥/추적사실을 우선 점검한다.
    if persona_id == "plausibility_absolutist":
        prompt += (
            "\n"
            "[아직 안 풀린 떡밥/복선 목록]과 [추적 중인 설정/인물 사실]을 우선적으로 참고해서, "
            "지금 첨부된 장면이나 시놉시스가 이 목록의 항목들과 모순되지 않는지, "
            "너무 오래 방치된 떡밥은 없는지 짚어라. 목록에 없는 새로운 설정이 "
            "갑자기 나왔다면 그것도 짚어라."
        )
    return prompt


def _reader_filled_worldbuilding_summary(worldbuilding_md: object) -> str:
    """Reuse world_import_analysis sheet schema: only non-empty sheet fields."""
    try:
        values = world_import_analysis.parse_worldbuilding_md(worldbuilding_md)
    except Exception:
        return ""
    lines: list[str] = []
    for section in world_import_analysis.WORLD_BUILDING_SCHEMA:
        filled: list[str] = []
        for field_id, label in section["fields"]:
            raw = values.get(field_id)
            if world_import_analysis.is_field_empty(raw):
                continue
            text = plain_text_from_content(str(raw or "")).strip()
            if not text:
                continue
            if len(text) > 220:
                text = text[:220] + "…"
            filled.append(f"- {label}: {text}")
        if filled:
            lines.append(str(section["title"]))
            lines.extend(filled)
    legacy = values.get("legacy") if isinstance(values, dict) else ""
    if not world_import_analysis.is_field_empty(legacy):
        text = plain_text_from_content(str(legacy or "")).strip()
        if text:
            if len(text) > 400:
                text = text[:400] + "…"
            lines.append("기타 · 기존 메모")
            lines.append(f"- {text}")
    summary = "\n".join(lines).strip()
    if len(summary) > READER_CHAT_WORLD_CAP:
        summary = summary[:READER_CHAT_WORLD_CAP] + "…"
    return summary


def _reader_project_index_block(work_id: object) -> str:
    """Format existing project_index row for virtual-reader context (read-only)."""
    try:
        project_id = int(str(work_id or "").strip())
    except (TypeError, ValueError):
        return ""
    if project_id <= 0:
        return ""
    try:
        with database() as connection:
            row = connection.execute(
                "SELECT characters_json, world_rules_json, timeline_json, "
                "open_threads_json, tracked_facts_json "
                "FROM project_index WHERE project_id = ?",
                (project_id,),
            ).fetchone()
    except sqlite3.OperationalError:
        return ""
    if row is None:
        return ""

    parse_list = SuperToryHandler._parse_json_list
    normalize_facts = SuperToryHandler._normalize_tracked_facts
    characters = [
        str(item).strip()
        for item in parse_list(row["characters_json"])
        if str(item).strip()
    ]
    world_rules = [
        str(item).strip()
        for item in parse_list(row["world_rules_json"])
        if str(item).strip()
    ]
    timeline = [
        str(item).strip()
        for item in parse_list(row["timeline_json"])
        if str(item).strip()
    ]
    open_threads = [
        str(item).strip()
        for item in parse_list(row["open_threads_json"])
        if str(item).strip()
    ]
    # tracked_facts_json NULL (pre-048) → normalize returns []; omit quietly
    tracked_raw = None
    try:
        tracked_raw = row["tracked_facts_json"]
    except (KeyError, IndexError, TypeError):
        tracked_raw = None
    if tracked_raw is None:
        tracked_facts: list = []
    else:
        tracked_facts = normalize_facts(tracked_raw)

    sections: list[str] = []
    if timeline:
        sections.append(
            "[지금까지 전개 - 실제 원고 문장 아님, 요약임]\n"
            + "\n".join(f"- {line}" for line in timeline)
        )
    if open_threads:
        sections.append(
            "[아직 안 풀린 떡밥/복선 목록]\n"
            + "\n".join(f"- {line}" for line in open_threads)
        )
    if tracked_facts:
        fact_lines: list[str] = []
        for fact in tracked_facts:
            if not isinstance(fact, dict):
                continue
            category = str(fact.get("category") or "").strip()
            subject = str(fact.get("subject") or "").strip()
            attribute = str(fact.get("attribute") or "").strip()
            value = str(fact.get("value") or "").strip()
            since = str(fact.get("since_scene") or "").strip()
            head = " / ".join(part for part in (subject, attribute) if part)
            bits = []
            if category:
                bits.append(f"[{category}]")
            if head:
                bits.append(head)
            if value:
                bits.append(f"= {value}")
            line = " ".join(bits).strip()
            if since:
                line = f"{line} (since: {since})" if line else f"(since: {since})"
            if line:
                fact_lines.append(f"- {line}")
        if fact_lines:
            sections.append(
                "[추적 중인 설정/인물 사실]\n" + "\n".join(fact_lines)
            )
    meta_bits: list[str] = []
    if characters:
        meta_bits.append("등장 인물: " + ", ".join(characters))
    if world_rules:
        meta_bits.append(
            "확립된 세계관·설정:\n" + "\n".join(f"- {rule}" for rule in world_rules)
        )
    if meta_bits:
        sections.append("\n".join(meta_bits))
    if not sections:
        return ""
    return (
        "[프로젝트 누적 정보]\n"
        "아래는 회차 인덱스를 모아 둔 내부 요약입니다. 실제 원고 문장이 아니며, "
        "설정집 시놉시스와도 별개입니다.\n\n"
        + "\n\n".join(sections)
    )


def _reader_dynamic_context(
    work_id: object, episode_content: str | None = None
) -> str:
    """Live work genre + settings + project_index (+ optional shared manuscript)."""
    work_key = str(work_id or "").strip()
    title = ""
    main_genre = ""
    sub_genre = ""
    synopsis_plain = ""
    world_summary = ""
    if work_key:
        with database() as connection:
            try:
                row = connection.execute(
                    "SELECT title, main_genre, sub_genre, description_md, worldbuilding_md "
                    "FROM project WHERE id = ? AND deleted_at IS NULL",
                    (work_key,),
                ).fetchone()
            except sqlite3.OperationalError:
                row = connection.execute(
                    "SELECT title, main_genre, sub_genre FROM project "
                    "WHERE id = ? AND deleted_at IS NULL",
                    (work_key,),
                ).fetchone()
        if row is not None:
            title = str(row["title"] or "").strip()
            main_genre = str(row["main_genre"] or "").strip()
            sub_genre = str(row["sub_genre"] or "").strip()
            try:
                synopsis_plain = plain_text_from_content(
                    str(row["description_md"] or "")
                ).strip()
            except (KeyError, IndexError, TypeError):
                synopsis_plain = ""
            try:
                world_summary = _reader_filled_worldbuilding_summary(
                    row["worldbuilding_md"]
                )
            except (KeyError, IndexError, TypeError):
                world_summary = ""
    if synopsis_plain and len(synopsis_plain) > READER_CHAT_SYNOPSIS_CAP:
        synopsis_plain = synopsis_plain[:READER_CHAT_SYNOPSIS_CAP] + "…"
    main_label = SuperToryHandler._genre_display_label(None, main_genre)
    sub_label = SuperToryHandler._genre_display_label(None, sub_genre)
    parts = [
        "[작품 정보]",
        f"작품 제목: {title or '(없음)'}",
        f"메인 장르: {main_label}",
        f"서브 장르: {sub_label}",
    ]
    # 장르 → 시놉시스 → 세계관 → 누적 인덱스 → 원고
    settings_bits: list[str] = []
    if synopsis_plain:
        settings_bits.append(f"시놉시스 요약:\n{synopsis_plain}")
    if world_summary:
        settings_bits.append(f"세계관 설정 요약(채워진 항목만):\n{world_summary}")
    if settings_bits:
        parts.append("")
        parts.append(
            "[작품 설정 요약 — 설정집 정보이며 실제 원고 문장이 아님]\n"
            "아래는 작가가 설정집에 적어 둔 요약입니다. 본문 장면처럼 인용하거나 "
            "이 내용만으로 장면이 이미 쓰인 것처럼 단정하지 마세요.\n"
            + "\n\n".join(settings_bits)
        )
    index_block = _reader_project_index_block(work_key)
    if index_block:
        parts.append("")
        parts.append(index_block)
    manuscript = str(episode_content or "").strip()
    if manuscript:
        if len(manuscript) > READER_CHAT_EPISODE_CAP:
            manuscript = manuscript[:READER_CHAT_EPISODE_CAP] + "…"
        parts.append("")
        parts.append(f"다음은 작가가 공유한 원고 내용입니다:\n{manuscript}")
    else:
        parts.append("")
        parts.append(
            "[원고 미첨부]\n"
            "지금은 특정 장면 원고 없이, 시놉시스/세계관·누적 인덱스 정보만 가지고 "
            "대화하는 상황이다. "
            "구체적인 장면 평가를 요구받으면 '원고를 보여주시면 더 정확하게 봐드릴 수 있어요' "
            "같은 식으로 자연스럽게 유도해라."
        )
    return "\n".join(parts)


def touch_project_opened(connection: sqlite3.Connection, project_id: int) -> str:
    """Stamp last_opened_at so recent-first list ordering stays current."""
    stamp = utc_timestamp_now()
    connection.execute(
        "UPDATE project SET last_opened_at = ? "
        "WHERE id = ? AND deleted_at IS NULL",
        (stamp, project_id),
    )
    row = connection.execute(
        "SELECT last_opened_at FROM project WHERE id = ?",
        (project_id,),
    ).fetchone()
    return str((row["last_opened_at"] if row else "") or stamp)


def project_list_order_sql(mode: str) -> str:
    if mode == "manual":
        return "ORDER BY list_sort_order ASC, id ASC"
    # Default: most recently opened first; never-opened fall back to created_at.
    return (
        "ORDER BY COALESCE(last_opened_at, created_at) DESC, id DESC"
    )


def serialize_project_list_row(row: sqlite3.Row | dict) -> dict:
    item = as_dict(row)
    item["synopsis_md"] = item.get("description_md") or ""
    item["logline_md"] = item.get("logline_md") or ""
    item["intro_md"] = item.get("intro_md") or ""
    item["intent_md"] = item.get("intent_md") or ""
    item["tory_priority_md"] = item.get("tory_priority_md") or ""
    item["outline_summary"] = item.get("outline_summary") or ""
    try:
        raw_link = item.get("linked_success_profile_id")
        item["linked_success_profile_id"] = (
            int(raw_link) if raw_link not in (None, "", 0, "0") else None
        )
    except (TypeError, ValueError):
        item["linked_success_profile_id"] = None
    item["main_genre"] = item.get("main_genre") or ""
    item["sub_genre"] = item.get("sub_genre") or ""
    item["genre_detail"] = item.get("genre_detail") or ""
    item["content_rating"] = item.get("content_rating") or ""
    item["keywords"] = parse_project_keywords(item.get("keywords"))
    item["import_delimiter_config"] = parse_import_delimiter_config(
        item.get("import_delimiter_config")
    )
    item["last_opened_at"] = item.get("last_opened_at") or None
    try:
        item["list_sort_order"] = int(item.get("list_sort_order") or 0)
    except (TypeError, ValueError):
        item["list_sort_order"] = 0
    return attach_cluster_id(item)


def list_projects_payload(connection: sqlite3.Connection) -> list[dict]:
    mode = project_list_mode(connection)
    # linked_success_profile_id added in migration 026 — tolerate older DBs mid-migrate.
    cols = "id, title, description_md, logline_md, worldbuilding_md, intro_md, intent_md, "
    cols += "tory_priority_md, outline_summary, "
    cols += "default_language, goal_word_count, "
    cols += "purpose, main_genre, sub_genre, keywords, uuid, package_path, "
    cols += "last_opened_at, list_sort_order, created_at, updated_at"
    try:
        connection.execute("SELECT linked_success_profile_id FROM project LIMIT 1")
        cols += ", linked_success_profile_id"
    except sqlite3.OperationalError:
        pass
    try:
        connection.execute("SELECT import_delimiter_config FROM project LIMIT 1")
        cols += ", import_delimiter_config"
    except sqlite3.OperationalError:
        pass
    try:
        connection.execute("SELECT cluster_id FROM project LIMIT 1")
        cols += ", cluster_id"
    except sqlite3.OperationalError:
        pass
    try:
        connection.execute("SELECT genre_detail FROM project LIMIT 1")
        cols += ", genre_detail"
    except sqlite3.OperationalError:
        pass
    try:
        connection.execute("SELECT content_rating FROM project LIMIT 1")
        cols += ", content_rating"
    except sqlite3.OperationalError:
        pass
    rows = connection.execute(
        f"SELECT {cols} "
        f"FROM project WHERE deleted_at IS NULL {project_list_order_sql(mode)}"
    ).fetchall()
    payload = [serialize_project_list_row(row) for row in rows]
    for item in payload:
        item["list_mode"] = mode
    return payload


def writing_day_payload(row: sqlite3.Row | dict | None) -> dict | None:
    if not row:
        return None
    data = dict(row) if not isinstance(row, dict) else row
    breakdown = {}
    raw = data.get("breakdown_json") or "{}"
    try:
        parsed = json.loads(raw) if isinstance(raw, str) else raw
        if isinstance(parsed, dict):
            breakdown = {
                str(k): max(0, int(v or 0))
                for k, v in parsed.items()
            }
    except (TypeError, ValueError, json.JSONDecodeError):
        breakdown = {}
    return {
        "day": data.get("day_key") or data.get("day") or "",
        "chars_added": int(data.get("chars_added") or 0),
        "active_seconds": int(data.get("active_seconds") or 0),
        "session_count": int(data.get("session_count") or 0),
        "first_start_at": data.get("first_start_at") or None,
        "last_active_at": data.get("last_active_at") or None,
        "breakdown": breakdown,
    }


def parse_import_delimiter_config(raw: object) -> dict | None:
    """Parse stored project.import_delimiter_config JSON, or None if empty."""
    return document_import.parse_stored_delimiter_config(raw)


def parse_project_keywords(raw: object) -> list[str]:
    """Normalise project keyword tags to a unique ordered list of short labels."""
    if raw is None or raw == "":
        return []
    if isinstance(raw, str):
        text = raw.strip()
        if not text:
            return []
        try:
            parsed = json.loads(text)
            if isinstance(parsed, list):
                raw = parsed
            else:
                # Plain comma / newline separated text
                raw = re.split(r"[,，/\n|]+", text)
        except json.JSONDecodeError:
            raw = re.split(r"[,，/\n|]+", text)
    if not isinstance(raw, (list, tuple)):
        raise ValueError("키워드 형식이 올바르지 않습니다.")
    cleaned: list[str] = []
    seen: set[str] = set()
    for item in raw:
        label = str(item or "").strip()[:40]
        if not label or label in seen:
            continue
        seen.add(label)
        cleaned.append(label)
        if len(cleaned) >= 40:
            break
    return cleaned


def parse_overlays(raw: object) -> list[dict]:
    if raw is None or raw == "":
        return []
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except json.JSONDecodeError as error:
            raise ValueError("삽화 위 글 정보가 올바르지 않습니다.") from error
    if not isinstance(raw, list):
        raise ValueError("삽화 위 글 정보가 올바르지 않습니다.")
    cleaned: list[dict] = []
    for index, item in enumerate(raw):
        if not isinstance(item, dict):
            continue
        overlay_id = str(item.get("id") or f"ov-{index + 1}")[:64]
        text = str(item.get("text", ""))[:4000]
        try:
            x = max(0.0, min(95.0, float(item.get("x", 10))))
            y = max(0.0, min(95.0, float(item.get("y", 10))))
            width = max(10.0, min(100.0, float(item.get("width", 40))))
            font_size = max(10, min(72, int(item.get("fontSize", 18) or 18)))
        except (TypeError, ValueError) as error:
            raise ValueError("삽화 위 글 위치 정보가 올바르지 않습니다.") from error
        color = str(item.get("color", "#24211d"))[:32]
        if not re.fullmatch(r"#[0-9A-Fa-f]{3,8}|[a-zA-Z]+", color):
            color = "#24211d"
        align = str(item.get("align", "left"))
        if align not in {"left", "center", "right"}:
            align = "left"
        cleaned.append({
            "id": overlay_id,
            "text": text,
            "x": round(x, 2),
            "y": round(y, 2),
            "width": round(width, 2),
            "fontSize": font_size,
            "color": color,
            "align": align,
        })
    return cleaned[:40]


def parse_reference_links(raw: object) -> list[dict]:
    """Normalise scene reference materials: links and file refs.

    Link:  {id, kind:'link', title, url}
    File:  {id, kind:'file', title, sourceId, fileName, fileExt, viewer, url?}
    """
    if raw is None or raw == "":
        return []
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except json.JSONDecodeError as error:
            raise ValueError("참고 자료 정보가 올바르지 않습니다.") from error
    if not isinstance(raw, list):
        raise ValueError("참고 자료 정보가 올바르지 않습니다.")
    cleaned: list[dict] = []
    for index, item in enumerate(raw):
        if not isinstance(item, dict):
            continue
        kind = str(item.get("kind") or "link").strip().lower()
        if kind not in {"link", "file"}:
            kind = "file" if (item.get("fileName") or item.get("sourceId") or item.get("source_id")) else "link"
        link_id = str(item.get("id") or f"ref-{index + 1}")[:64]

        if kind == "file":
            title = str(item.get("title", "")).strip()[:200]
            file_name = str(item.get("fileName") or item.get("file_name") or "").strip()[:260]
            source_id = str(item.get("sourceId") or item.get("source_id") or "").strip()[:80]
            file_ext = str(item.get("fileExt") or item.get("file_ext") or "").strip()[:20]
            viewer = str(item.get("viewer") or "").strip()[:20]
            if not title and not file_name and not source_id:
                continue
            if not title:
                title = (file_name or "파일")[:80]
            entry: dict = {
                "id": link_id,
                "kind": "file",
                "title": title,
                "url": "",
                "sourceId": source_id,
                "fileName": file_name,
            }
            if file_ext:
                entry["fileExt"] = file_ext
            if viewer in {"pdf", "text"}:
                entry["viewer"] = viewer
            # Optional external url kept if present
            raw_url = str(item.get("url", "")).strip()
            if raw_url and re.match(r"^https?://", raw_url, re.IGNORECASE):
                entry["url"] = raw_url[:2000]
            cleaned.append(entry)
            continue

        url = str(item.get("url", "")).strip()
        if not url:
            continue
        # Allow bare domains by prefixing https://
        if not re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*:", url):
            url = "https://" + url
        if not re.match(r"^https?://", url, re.IGNORECASE):
            raise ValueError("참고 링크는 http 또는 https 주소만 넣을 수 있어요.")
        if len(url) > 2000:
            raise ValueError("참고 링크 주소가 너무 깁니다.")
        title = str(item.get("title", "")).strip()[:200]
        if not title:
            # Fallback label from host/path
            title = re.sub(r"^https?://(www\.)?", "", url, flags=re.IGNORECASE).split("/")[0] or "링크"
            title = title[:80]
        entry = {"id": link_id, "kind": "link", "title": title, "url": url}
        source_id = str(item.get("sourceId") or item.get("source_id") or "").strip()[:80]
        if source_id:
            entry["sourceId"] = source_id
        cleaned.append(entry)
    return cleaned[:40]


def illustration_public(row: sqlite3.Row | dict) -> dict:
    data = dict(row)
    data["overlays"] = parse_overlays(data.pop("overlays_json", "[]"))
    data["image_url"] = f"/api/illustrations/{data['id']}/image"
    return data


def as_dict(row: sqlite3.Row | None) -> dict | None:
    return dict(row) if row is not None else None


# Binder untitled labels (keep in sync with web/app.js UNTITLED_SCENE_TITLES).
UNTITLED_SCENE_TITLES = frozenset({"", "제목 없음", "새 씬", "새 하위 원고"})
BODY_PREVIEW_PLAIN_LIMIT = 1200
_OUTLINE_CONTENT_HEAD_SQL = (
    "CASE WHEN trim(COALESCE(s.title, '')) IN ('', '제목 없음', '새 씬', '새 하위 원고') "
    "THEN r.content_md ELSE NULL END AS content_head"
)


def plain_text_from_content(content: str, *, include_author_notes: bool = False) -> str:
    """Strip HTML for counts. Match editor innerText (div → one newline, p → blank line).

    Writer-only comment paragraphs (``data-author-note``) are removed by default
    so reader/export/stats never see them. Pass ``include_author_notes=True``
    for Tory writing-assist (continue/rewrite/etc.) that should honour in-draft
    author intent. Character/item auto-fill analysis must keep the default.
    """
    text = content or ""
    if not include_author_notes:
        text = author_note_blocks.strip_author_note_html(text)
    text = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", "", text)
    text = re.sub(r"(?i)<br\s*/?>", "\n", text)
    text = re.sub(r"(?i)</p\s*>", "\n\n", text)
    text = re.sub(r"(?i)</(div|h[1-6]|li|blockquote|tr)\s*>", "\n", text)
    text = re.sub(r"(?s)<[^>]+>", "", text)
    # Truncated HTML (e.g. outline used to cut at 1200 chars mid-attribute) has no
    # closing '>'. Drop that dangling opener so it cannot leak as visible text.
    text = re.sub(r"<[^>]*$", "", text)
    text = html_lib.unescape(text)
    text = text.replace("\xa0", " ").replace("\u200b", "")
    text = re.sub(r"[ \t]+\n", "\n", text)
    text = re.sub(r"[ \t]{2,}", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


def compute_text_stats(plain_text: str) -> dict:
    """Mirror web/app.js computeTextStats (Unicode code points, no-space, letters)."""
    text = (plain_text or "").replace("\r\n", "\n").replace("\r", "\n")
    text = text.replace("\xa0", " ").replace("\u200b", "")
    text = re.sub(r"\n{3,}", "\n\n", text).strip()
    chars_with_space = len(text)
    chars_no_space = sum(1 for ch in text if not ch.isspace())
    stripped = text.strip()
    words = len(re.findall(r"\S+", stripped)) if stripped else 0
    letters = sum(1 for ch in text if ch.isalnum())
    return {
        "chars_with_space": chars_with_space,
        "chars_no_space": chars_no_space,
        "words": words,
        "letters": letters,
    }


def first_sentence_preview(content: str, limit: int = 160) -> str:
    """First sentence (or line) of manuscript body for binder untitled titles.

    Strip tags from the full fragment first, then crop plain text. Cutting HTML
    before stripping can leave a sliced tag such as ``<br style="...`` as text.
    """
    plain = plain_text_from_content(content or "")
    if not plain:
        return ""
    if len(plain) > BODY_PREVIEW_PLAIN_LIMIT:
        plain = plain[:BODY_PREVIEW_PLAIN_LIMIT]
    compact = re.sub(r"\s+", " ", plain).strip()
    match = re.match(r"^(.+?(?:[.。!?？…]|$))(?:\s|$)", compact)
    sentence = (match.group(1) if match else compact).strip()
    if len(sentence) > limit:
        return sentence[: max(1, limit - 1)].rstrip() + "…"
    return sentence


def outline_body_preview(title: str, content: str | None) -> str:
    """Binder label for untitled scenes; titled scenes keep an empty preview."""
    if str(title or "").strip() not in UNTITLED_SCENE_TITLES:
        return ""
    return first_sentence_preview(content or "")


def word_count(markdown: str) -> int:
    """Count whitespace-separated tokens; HTML tags are ignored."""
    return len(re.findall(r"\S+", plain_text_from_content(markdown)))


def ensure_project_package(connection: sqlite3.Connection, project_id: int) -> dict:
    """Create/refresh the external .stg file for a project; return path fields."""
    row = connection.execute(
        "SELECT id, title, purpose, uuid, package_path FROM project "
        "WHERE id = ? AND deleted_at IS NULL",
        (project_id,),
    ).fetchone()
    if row is None:
        raise ValueError("작품을 찾을 수 없습니다.")
    project_uuid = row["uuid"] or project_package.new_project_uuid()
    purpose = row["purpose"] if "purpose" in row.keys() else "general_novel"
    package = project_package.create_or_update_package(
        projects_root().parent,
        project_uuid=project_uuid,
        title=row["title"],
        purpose=purpose or "general_novel",
        project_id=project_id,
        existing_path=row["package_path"],
    )
    connection.execute(
        "UPDATE project SET uuid = ?, package_path = ? WHERE id = ?",
        (project_uuid, str(package), project_id),
    )
    return {
        "uuid": project_uuid,
        "package_path": str(package),
        "package_name": package.name,
    }


def ensure_all_project_packages(connection: sqlite3.Connection) -> None:
    rows = connection.execute(
        "SELECT id FROM project WHERE deleted_at IS NULL ORDER BY id"
    ).fetchall()
    for row in rows:
        ensure_project_package(connection, row["id"])


def resolve_package_file(path: Path) -> int:
    """Return project id for a .stg package path."""
    data = project_package.read_package(path)
    project_uuid = str(data["uuid"])
    with database() as connection:
        row = connection.execute(
            "SELECT id, package_path FROM project WHERE uuid = ? AND deleted_at IS NULL",
            (project_uuid,),
        ).fetchone()
        if row is None and data.get("project_id") is not None:
            row = connection.execute(
                "SELECT id, package_path FROM project WHERE id = ? AND deleted_at IS NULL",
                (int(data["project_id"]),),
            ).fetchone()
        if row is None:
            raise ValueError(
                "이 .stg 파일에 해당하는 작품을 찾지 못했습니다. "
                "SuperTory 데이터 폴더가 그대로인지 확인해 주세요."
            )
        # Keep package_path in sync if the user moved/renamed the file.
        resolved = str(path.resolve())
        if row["package_path"] != resolved:
            connection.execute(
                "UPDATE project SET package_path = ? WHERE id = ?",
                (resolved, row["id"]),
            )
            # Refresh manifest contents at the new location.
            project = connection.execute(
                "SELECT id, title, purpose, uuid FROM project WHERE id = ?",
                (row["id"],),
            ).fetchone()
            project_package.write_package(
                path.resolve(),
                project_uuid=project["uuid"],
                title=project["title"],
                purpose=project["purpose"] or "general_novel",
                project_id=project["id"],
            )
        return int(row["id"])


def port_is_open(host: str, port: int) -> bool:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.settimeout(0.35)
        return sock.connect_ex((host, port)) == 0


def listening_pids(port: int) -> list[int]:
    """Return PIDs listening on TCP port (Windows netstat)."""
    if sys.platform != "win32":
        return []
    try:
        completed = subprocess.run(
            ["netstat", "-ano", "-p", "TCP"],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            check=False,
        )
    except OSError:
        return []
    pids: list[int] = []
    needle = f":{port}"
    for line in completed.stdout.splitlines():
        if "LISTENING" not in line.upper():
            continue
        if needle not in line:
            continue
        # Typical: TCP    127.0.0.1:8765    0.0.0.0:0    LISTENING    1234
        parts = line.split()
        if len(parts) < 5:
            continue
        local = parts[1] if len(parts) >= 2 else ""
        if not local.endswith(needle):
            continue
        try:
            pid = int(parts[-1])
        except ValueError:
            continue
        if pid > 0 and pid not in pids:
            pids.append(pid)
    return pids


def stop_server_on_port(port: int) -> bool:
    """Stop an already-running SuperTORY instance so restarts load new code."""
    pids = listening_pids(port)
    if not pids:
        return False
    stopped = False
    for pid in pids:
        if pid == os.getpid():
            continue
        try:
            if sys.platform == "win32":
                subprocess.run(
                    ["taskkill", "/PID", str(pid), "/F"],
                    capture_output=True,
                    check=False,
                )
            else:
                os.kill(pid, 15)
            stopped = True
            print(f"이전 SuperTORY 서버(PID {pid})를 종료하고 새 버전으로 다시 시작합니다.")
        except OSError as error:
            print(f"이전 서버(PID {pid})를 종료하지 못했습니다: {error}")
    # Brief wait so the port is released.
    if stopped:
        for _ in range(20):
            if not port_is_open(HOST, port):
                break
            time.sleep(0.1)
    return stopped


def reveal_in_explorer(path: Path) -> None:
    path = Path(path)
    if sys.platform != "win32":
        return
    if path.is_file():
        subprocess.Popen(["explorer", "/select,", str(path.resolve())])  # noqa: S603
    elif path.is_dir():
        subprocess.Popen(["explorer", str(path.resolve())])  # noqa: S603
    else:
        subprocess.Popen(["explorer", str(projects_root())])  # noqa: S603


